def choose_move(observation):
    wx = observation.get('grid_width', 0)
    wy = observation.get('grid_height', 0)
    pos = observation.get('self_position', [0, 0])
    x, y = pos[0], pos[1]
    resources = observation.get('resources', [])
    opponent_pos = observation.get('opponent_position', None)

    targets = []

    if resources:
        targets.extend(resources)
    if opponent_pos:
        targets.append(opponent_pos)

    if targets:
        # Find the closest target
        target = min(targets, key=lambda p: abs(p[0] - x) + abs(p[1] - y))
        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        # Limit moves to -1, 0, 1
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        return [dx, dy]
    return [0, 0]
